<script setup lang="ts">import{onMounted,ref}from'vue';import{api,session}from'../api';const me=ref<any>(),email=ref(''),currentPassword=ref(''),newPassword=ref(''),message=ref(''),error=ref('');async function load(){me.value=await api('/api/auth/me');email.value=me.value.email||''}async function save(){error.value='';try{me.value=await api('/api/auth/profile',{method:'PUT',body:JSON.stringify({email:email.value})});message.value='资料已保存'}catch(e:any){error.value=e.message}}async function password(){error.value='';try{await api('/api/auth/password',{method:'POST',body:JSON.stringify({current_password:currentPassword.value,new_password:newPassword.value})});session.token='';location.assign('/login')}catch(e:any){error.value=e.message}}onMounted(load)</script>
<template><div class="page-heading"><div><span class="eyebrow">账号</span><h1>个人设置</h1><p>维护资料和登录密码。</p></div></div><div class="settings-grid"><section class="card form-card"><h2>账号资料</h2><label>用户名<input :value="me?.username" disabled></label><label>邮箱（可选）<input v-model="email" type="email"></label><button class="btn" @click="save">保存资料</button></section><section class="card form-card"><h2>修改密码</h2><label>当前密码<input v-model="currentPassword" type="password"></label><label>新密码<input v-model="newPassword" type="password" minlength="8"></label><button class="btn" @click="password">修改并重新登录</button></section></div><p v-if="message" class="notice">{{message}}</p><p v-if="error" class="error">{{error}}</p></template>
